-- ============================================================================
-- Function: private.resolve_airport_page_context
-- Feature: Interactive pSEO
-- Purpose: Resolve normalized airport and localized page identity.
-- Responsibilities: Return IDs and the current published read-model version.
-- ============================================================================

CREATE OR REPLACE FUNCTION private.resolve_airport_page_context(
  p_airport_iata TEXT,
  p_locale TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
STABLE
SECURITY INVOKER
SET search_path = ''
AS $$
DECLARE
  v_airport_id UUID;
  v_city_id UUID;
  v_country_id UUID;
  v_airport_page_id UUID;
  v_pseo_page_id UUID;
  v_data_version UUID;
BEGIN
  SELECT
    airport.id,
    airport.city_id,
    airport.country_id
  INTO
    v_airport_id,
    v_city_id,
    v_country_id
  FROM public.airports airport
  WHERE airport.iata = p_airport_iata;

  IF v_airport_id IS NULL THEN
    RETURN jsonb_build_object(
      'data', NULL,
      'error', jsonb_build_object(
        'code', 'ERR_AIRPORT_NOT_FOUND',
        'message', 'Airport was not found.'
      )
    );
  END IF;

  SELECT
    airport_page.id,
    airport_page.pseo_page_id,
    airport_page.data_version
  INTO
    v_airport_page_id,
    v_pseo_page_id,
    v_data_version
  FROM public.airport_pages airport_page
  WHERE airport_page.airport_id = v_airport_id
    AND airport_page.locale = p_locale;

  IF v_airport_page_id IS NULL THEN
    RETURN jsonb_build_object(
      'data', NULL,
      'error', jsonb_build_object(
        'code', 'ERR_AIRPORT_PAGE_NOT_FOUND',
        'message', 'Airport page was not found.'
      )
    );
  END IF;

  RETURN jsonb_build_object(
    'data', jsonb_build_object(
      'airport_id', v_airport_id,
      'airport_page_id', v_airport_page_id,
      'pseo_page_id', v_pseo_page_id,
      'city_id', v_city_id,
      'country_id', v_country_id,
      'data_version', v_data_version
    ),
    'error', NULL
  );
END;
$$;

REVOKE ALL ON FUNCTION private.resolve_airport_page_context(TEXT, TEXT)
FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION private.resolve_airport_page_context(TEXT, TEXT) TO service_role;

-- >>> supabase/sql_src/functions/pseo/city/get_city_airport_route_stats.sql

-- ============================================================================
-- Function: private.get_city_airport_route_stats
-- Feature: Interactive pSEO
-- Purpose: Derive reusable route coverage and airline-model statistics for city airports.
-- Responsibilities: Keep airport-card metrics version-consistent and free of editorial data.
-- Notes: Destination percentages describe distinct destination-city coverage.
-- ============================================================================

CREATE OR REPLACE FUNCTION private.get_city_airport_route_stats(
  p_city_id UUID,
  p_data_version UUID
)
RETURNS TABLE (
  airport_id UUID,
  direct_counterpart_city_count INTEGER,
  domestic_destination_count INTEGER,
  international_destination_count INTEGER,
  domestic_destination_percentage INTEGER,
  international_destination_percentage INTEGER,
  airline_count INTEGER,
  dominant_airline_business_model TEXT
)
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path = ''
AS $$
  WITH city_context AS (
    SELECT city.country_id
    FROM public.cities city
    WHERE city.id = p_city_id
  ),
  airport_routes AS (
    SELECT
      city_route.origin_airport_id AS airport_id,
      city_route.destination_city_id,
      city_route.destination_country_id,
      city_route.operating_airline_id,
      airline.business_model,
      COALESCE(city_route.frequency_per_week, 1) AS business_model_weight
    FROM public.pseo_direct_routes city_route
    JOIN public.airlines airline
      ON airline.id = city_route.operating_airline_id
    WHERE city_route.origin_city_id = p_city_id
      AND city_route.data_version = p_data_version
  ),
  route_stats AS (
    SELECT
      airport_route.airport_id,
      count(DISTINCT airport_route.destination_city_id)::INTEGER AS direct_counterpart_city_count,
      count(DISTINCT airport_route.destination_city_id)
        FILTER (
          WHERE airport_route.destination_country_id = city_context.country_id
        )::INTEGER AS domestic_destination_count,
      count(DISTINCT airport_route.destination_city_id)
        FILTER (
          WHERE airport_route.destination_country_id <> city_context.country_id
        )::INTEGER AS international_destination_count,
      count(DISTINCT airport_route.operating_airline_id)::INTEGER AS airline_count
    FROM airport_routes airport_route
    CROSS JOIN city_context
    GROUP BY airport_route.airport_id
  ),
  business_model_scores AS (
    SELECT
      airport_route.airport_id,
      airport_route.business_model,
      sum(airport_route.business_model_weight) AS score
    FROM airport_routes airport_route
    GROUP BY
      airport_route.airport_id,
      airport_route.business_model
  ),
  dominant_business_models AS (
    SELECT DISTINCT ON (business_model_score.airport_id)
      business_model_score.airport_id,
      business_model_score.business_model
    FROM business_model_scores business_model_score
    ORDER BY
      business_model_score.airport_id,
      business_model_score.score DESC,
      business_model_score.business_model
  )
  SELECT
    airport.id,
    COALESCE(route_stat.direct_counterpart_city_count, 0),
    COALESCE(route_stat.domestic_destination_count, 0),
    COALESCE(route_stat.international_destination_count, 0),
    CASE
      WHEN COALESCE(route_stat.direct_counterpart_city_count, 0) = 0 THEN 0
      ELSE round(
        route_stat.domestic_destination_count::NUMERIC
        * 100
        / route_stat.direct_counterpart_city_count
      )::INTEGER
    END,
    CASE
      WHEN COALESCE(route_stat.direct_counterpart_city_count, 0) = 0 THEN 0
      ELSE round(
        route_stat.international_destination_count::NUMERIC
        * 100
        / route_stat.direct_counterpart_city_count
      )::INTEGER
    END,
    COALESCE(route_stat.airline_count, 0),
    COALESCE(dominant_business_model.business_model, 'unknown')
  FROM public.airports airport
  LEFT JOIN route_stats route_stat
    ON route_stat.airport_id = airport.id
  LEFT JOIN dominant_business_models dominant_business_model
    ON dominant_business_model.airport_id = airport.id
  WHERE airport.city_id = p_city_id
    AND airport.status = 'active';
$$;

REVOKE ALL ON FUNCTION private.get_city_airport_route_stats(UUID, UUID)
FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION private.get_city_airport_route_stats(UUID, UUID) TO service_role;

-- >>> supabase/sql_src/functions/pseo/city/get_city_quick_facts.sql

-- ============================================================================
-- Function: private.get_city_quick_facts
-- Feature: Interactive pSEO
-- Purpose: Derive one version-consistent city Quick Facts read model.
-- Responsibilities: Count city coverage and resolve shortest and longest direct destinations.
-- Notes: Route extrema use stored recurring schedules, not live dated availability.
-- ============================================================================

CREATE OR REPLACE FUNCTION private.get_city_quick_facts(
  p_city_id UUID,
  p_data_version UUID
)
RETURNS JSONB
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path = ''
AS $$
  WITH city_context AS (
    SELECT
      city.id,
      city.slug
    FROM public.cities city
    WHERE city.id = p_city_id
  ),
  routes AS MATERIALIZED (
    SELECT city_route.*
    FROM public.pseo_direct_routes city_route
    WHERE city_route.origin_city_id = p_city_id
      AND city_route.data_version = p_data_version
  ),
  route_counts AS (
    SELECT
      count(DISTINCT route.destination_city_id)::INTEGER AS direct_counterpart_city_count,
      count(DISTINCT route.destination_country_id)::INTEGER AS direct_counterpart_country_count,
      count(DISTINCT route.operating_airline_id)::INTEGER AS airline_count
    FROM routes route
  ),
  shortest_route AS (
    SELECT jsonb_build_object(
      'destination_name', destination_city.name,
      'destination_slug', destination_city.slug,
      'route_path', format(
        '/flights/%s-to-%s',
        city_context.slug,
        destination_city.slug
      ),
      'duration_minutes', route.shortest_duration_minutes
    ) AS value
    FROM routes route
    CROSS JOIN city_context
    JOIN public.cities destination_city
      ON destination_city.id = route.destination_city_id
    ORDER BY
      route.shortest_duration_minutes,
      destination_city.name
    LIMIT 1
  ),
  longest_route AS (
    SELECT jsonb_build_object(
      'destination_name', destination_city.name,
      'destination_slug', destination_city.slug,
      'route_path', format(
        '/flights/%s-to-%s',
        city_context.slug,
        destination_city.slug
      ),
      'duration_minutes', route.longest_duration_minutes
    ) AS value
    FROM routes route
    CROSS JOIN city_context
    JOIN public.cities destination_city
      ON destination_city.id = route.destination_city_id
    ORDER BY
      route.longest_duration_minutes DESC,
      destination_city.name
    LIMIT 1
  )
  SELECT jsonb_build_object(
    'airport_count', (
      SELECT count(*)::INTEGER
      FROM public.airports airport
      WHERE airport.city_id = p_city_id
        AND airport.status = 'active'
    ),
    'direct_counterpart_city_count', route_counts.direct_counterpart_city_count,
    'direct_counterpart_country_count', route_counts.direct_counterpart_country_count,
    'airline_count', route_counts.airline_count,
    'shortest_route', (
      SELECT shortest_route.value
      FROM shortest_route
    ),
    'longest_route', (
      SELECT longest_route.value
      FROM longest_route
    )
  )
  FROM route_counts;
$$;

REVOKE ALL ON FUNCTION private.get_city_quick_facts(UUID, UUID)
FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION private.get_city_quick_facts(UUID, UUID) TO service_role;

-- >>> supabase/sql_src/functions/pseo/city/get_city_route_map.sql

-- ============================================================================
-- Function: private.get_city_route_map
-- Feature: Route Map
-- Purpose: Build one version-consistent city-to-city direct-route map read model.
-- Responsibilities: Filter routes, aggregate destination cities, and preserve map geometry.
-- Notes: Destination cities without coordinates are counted but omitted from rendered geometry.
-- ============================================================================

CREATE OR REPLACE FUNCTION private.get_city_route_map(
  p_city_id UUID,
  p_city_slug TEXT,
  p_data_version UUID,
  p_origin_airports TEXT[],
  p_airlines TEXT[],
  p_destination_countries TEXT[],
  p_max_duration_minutes INTEGER,
  p_departure_window TEXT,
  p_limit INTEGER
)
RETURNS JSONB
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path = ''
AS $$
  WITH origin AS (
    SELECT
      city.name,
      city.slug,
      city.latitude,
      city.longitude
    FROM public.cities city
    WHERE city.id = p_city_id
  ),
  filtered AS MATERIALIZED (
    SELECT
      city_route.*,
      origin_airport.iata AS origin_airport_iata,
      destination_airport.iata AS destination_airport_iata,
      operating_airline.iata AS operating_airline_iata,
      destination_country.iso2 AS destination_country_iso2,
      destination_country.name AS destination_country_name,
      destination_city.name AS destination_city_name,
      destination_city.slug AS destination_city_slug,
      destination_city.latitude AS destination_city_latitude,
      destination_city.longitude AS destination_city_longitude
    FROM public.pseo_direct_routes city_route
    JOIN public.airports origin_airport
      ON origin_airport.id = city_route.origin_airport_id
    JOIN public.airports destination_airport
      ON destination_airport.id = city_route.destination_airport_id
    JOIN public.airlines operating_airline
      ON operating_airline.id = city_route.operating_airline_id
    JOIN public.countries destination_country
      ON destination_country.id = city_route.destination_country_id
    JOIN public.cities destination_city
      ON destination_city.id = city_route.destination_city_id
    WHERE city_route.origin_city_id = p_city_id
      AND city_route.data_version = p_data_version
      AND (
        cardinality(p_origin_airports) = 0
        OR origin_airport.iata = ANY(p_origin_airports)
      )
      AND (
        cardinality(p_airlines) = 0
        OR operating_airline.iata = ANY(p_airlines)
      )
      AND (
        cardinality(p_destination_countries) = 0
        OR destination_country.iso2 = ANY(p_destination_countries)
      )
      AND (
        p_max_duration_minutes IS NULL
        OR city_route.shortest_duration_minutes <= p_max_duration_minutes
      )
      AND (
        p_departure_window IS NULL
        OR (
          p_departure_window = 'morning'
          AND city_route.earliest_departure_time >= TIME '05:00'
          AND city_route.earliest_departure_time < TIME '12:00'
        )
        OR (
          p_departure_window = 'afternoon'
          AND city_route.earliest_departure_time >= TIME '12:00'
          AND city_route.earliest_departure_time < TIME '17:00'
        )
        OR (
          p_departure_window = 'evening'
          AND city_route.earliest_departure_time >= TIME '17:00'
          AND city_route.earliest_departure_time < TIME '21:00'
        )
        OR (
          p_departure_window = 'night'
          AND (
            city_route.earliest_departure_time >= TIME '21:00'
            OR city_route.earliest_departure_time < TIME '05:00'
          )
        )
      )
  ),
  destinations AS (
    SELECT
      filtered.destination_city_id,
      filtered.destination_city_name,
      filtered.destination_city_slug,
      filtered.destination_country_iso2,
      filtered.destination_country_name,
      filtered.destination_city_latitude,
      filtered.destination_city_longitude,
      jsonb_agg(
        DISTINCT filtered.origin_airport_iata
        ORDER BY filtered.origin_airport_iata
      ) AS origin_airports,
      jsonb_agg(
        DISTINCT filtered.destination_airport_iata
        ORDER BY filtered.destination_airport_iata
      ) AS destination_airports,
      jsonb_agg(
        DISTINCT filtered.operating_airline_iata
        ORDER BY filtered.operating_airline_iata
      ) AS airlines,
      CASE
        WHEN count(filtered.frequency_per_week) = 0 THEN NULL
        ELSE sum(filtered.frequency_per_week)
      END AS frequency_per_week,
      min(filtered.shortest_duration_minutes) AS shortest_duration_minutes,
      min(filtered.confidence_score) AS confidence_score
    FROM filtered
    GROUP BY
      filtered.destination_city_id,
      filtered.destination_city_name,
      filtered.destination_city_slug,
      filtered.destination_country_iso2,
      filtered.destination_country_name,
      filtered.destination_city_latitude,
      filtered.destination_city_longitude
  ),
  ranked AS (
    SELECT destinations.*
    FROM destinations
    WHERE destinations.destination_city_latitude IS NOT NULL
      AND destinations.destination_city_longitude IS NOT NULL
    ORDER BY
      COALESCE(destinations.frequency_per_week, 0) DESC,
      destinations.shortest_duration_minutes,
      destinations.confidence_score DESC,
      destinations.destination_city_name
    LIMIT p_limit
  )
  SELECT jsonb_build_object(
    'origin', (
      SELECT jsonb_build_object(
        'type', 'city',
        'name', origin.name,
        'slug', origin.slug,
        'latitude', origin.latitude,
        'longitude', origin.longitude
      )
      FROM origin
    ),
    'destinations', COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'city_name', ranked.destination_city_name,
          'city_slug', ranked.destination_city_slug,
          'country_iso2', ranked.destination_country_iso2,
          'country_name', ranked.destination_country_name,
          'latitude', ranked.destination_city_latitude,
          'longitude', ranked.destination_city_longitude,
          'route_path', format(
            '/flights/%s-to-%s',
            p_city_slug,
            ranked.destination_city_slug
          ),
          'origin_airports', ranked.origin_airports,
          'destination_airports', ranked.destination_airports,
          'airlines', ranked.airlines,
          'shortest_duration_minutes', ranked.shortest_duration_minutes,
          'frequency_per_week', ranked.frequency_per_week
        )
        ORDER BY
          COALESCE(ranked.frequency_per_week, 0) DESC,
          ranked.shortest_duration_minutes,
          ranked.confidence_score DESC,
          ranked.destination_city_name
      )
      FROM ranked
    ), '[]'::JSONB),
    'total', (
      SELECT count(*)::INTEGER
      FROM destinations
    ),
    'omitted_destination_count', (
      SELECT count(*)::INTEGER
      FROM destinations
      WHERE destinations.destination_city_latitude IS NULL
        OR destinations.destination_city_longitude IS NULL
    )
  );
$$;

REVOKE ALL ON FUNCTION private.get_city_route_map(
  UUID,
  TEXT,
  UUID,
  TEXT[],
  TEXT[],
  TEXT[],
  INTEGER,
  TEXT,
  INTEGER
)
FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION private.get_city_route_map(
  UUID,
  TEXT,
  UUID,
  TEXT[],
  TEXT[],
  TEXT[],
  INTEGER,
  TEXT,
  INTEGER
) TO service_role;

-- >>> supabase/sql_src/functions/pseo/city/build_city_page_payload.sql

-- ============================================================================
-- Function: private.build_city_page_payload
-- Feature: Interactive pSEO
-- Purpose: Return one bounded, frontend-ready city pSEO page payload.
-- Responsibilities: Validate identity, resolve reviewed content, and group page modules.
-- Notes: Indexability metadata is returned from Postgres and is never inferred by the transport.
-- ============================================================================

CREATE OR REPLACE FUNCTION private.build_city_page_payload(p_input JSONB)
RETURNS JSONB
LANGUAGE plpgsql
STABLE
SECURITY INVOKER
SET search_path = ''
AS $$
DECLARE
  ------------------------------------------------------------------
  -- Input
  ------------------------------------------------------------------
  v_city_slug TEXT;
  v_locale TEXT;
  v_route_direction TEXT;
  v_destination_limit INTEGER := 8;

  ------------------------------------------------------------------
  -- Resolved page
  ------------------------------------------------------------------
  v_city_id UUID;
  v_city_page_id UUID;
  v_pseo_page_id UUID;
  v_data_version UUID;
  v_identity JSONB;
  v_context JSONB;
  v_result JSONB;
BEGIN
  -- STEP 01: Parse the city-page identity shared by pSEO read RPCs.
  v_identity := private.parse_city_page_identity(p_input);

  IF v_identity #>> '{error,code}' IS NOT NULL THEN
    RETURN private.build_rpc_error(
      'null'::JSONB,
      v_identity #>> '{error,code}',
      v_identity #>> '{error,message}'
    );
  END IF;

  v_city_slug := v_identity #>> '{data,city_slug}';
  v_locale := v_identity #>> '{data,locale}';
  v_route_direction := v_identity #>> '{data,route_direction}';

  IF p_input ? 'destination_limit' THEN
    IF jsonb_typeof(p_input->'destination_limit') <> 'number' THEN
      RETURN private.build_rpc_error(
        'null'::JSONB,
        'ERR_INVALID_REQUEST',
        'destination_limit must be an integer.'
      );
    END IF;
    v_destination_limit := (p_input->>'destination_limit')::INTEGER;
  END IF;

  IF v_destination_limit NOT BETWEEN 1 AND 24 THEN
    RETURN private.build_rpc_error(
      'null'::JSONB,
      'ERR_INVALID_REQUEST',
      'destination_limit is outside accepted bounds.'
    );
  END IF;

  -- STEP 02: Resolve the city and reviewed page identity.
  v_context := private.resolve_city_page_context(
    v_city_slug,
    v_locale,
    v_route_direction
  );

  IF v_context #>> '{error,code}' IS NOT NULL THEN
    RETURN private.build_rpc_error(
      'null'::JSONB,
      v_context #>> '{error,code}',
      v_context #>> '{error,message}'
    );
  END IF;

  v_city_id := (v_context #>> '{data,city_id}')::UUID;
  v_city_page_id := (v_context #>> '{data,city_page_id}')::UUID;
  v_pseo_page_id := (v_context #>> '{data,pseo_page_id}')::UUID;
  v_data_version := (v_context #>> '{data,data_version}')::UUID;

  -- STEP 03: Assemble a bounded page payload from one published data version.
  SELECT jsonb_build_object(
    'data', jsonb_build_object(
      'city', jsonb_build_object(
        'id', city.id,
        'name', city.name,
        'slug', city.slug,
        'latitude', city.latitude,
        'longitude', city.longitude,
        'timezone', city.timezone
      ),
      'country', jsonb_build_object(
        'iso2', country.iso2,
        'iso3', country.iso3,
        'name', country.name,
        'slug', country.slug,
        'region', country.region,
        'subregion', country.subregion
      ),
      'page', jsonb_build_object(
        'h1', city_page.h1,
        'subheadline', city_page.subheadline,
        'seo_title', city_page.seo_title,
        'meta_description', city_page.meta_description,
        'og_title', city_page.og_title,
        'og_description', city_page.og_description,
        'og_image_path', city_page.og_image_path,
        'intro', city_page.intro,
        'airport_summary', city_page.airport_summary,
        'status', city_page.status
      ),
      'airports', COALESCE((
        SELECT jsonb_agg(
          jsonb_build_object(
            'iata', airport.iata,
            'icao', airport.icao,
            'name', airport.name,
            'slug', airport.slug,
            'airport_type', airport.airport_type,
            'latitude', airport.latitude,
            'longitude', airport.longitude,
            'timezone', airport.timezone,
            'is_primary', airport.id = city_page.primary_airport_id,
            'direct_destinations', (
              SELECT count(DISTINCT city_route.destination_city_id)
              FROM public.pseo_direct_routes city_route
              WHERE city_route.origin_airport_id = airport.id
                AND city_route.data_version = v_data_version
            ),
            'airlines', (
              SELECT count(DISTINCT city_route.operating_airline_id)
              FROM public.pseo_direct_routes city_route
              WHERE city_route.origin_airport_id = airport.id
                AND city_route.data_version = v_data_version
            )
          )
          ORDER BY
            (airport.id = city_page.primary_airport_id) DESC,
            airport.iata
        )
        FROM public.airports airport
        WHERE airport.city_id = city.id
          AND airport.status = 'active'
      ), '[]'::JSONB),
      'quick_facts', jsonb_build_object(
        'airports', city_page.airport_count,
        'direct_destinations', city_page.direct_counterpart_city_count,
        'direct_countries', city_page.direct_counterpart_country_count,
        'airlines', city_page.airline_count,
        'shortest_route_minutes', city_page.shortest_route_minutes,
        'longest_route_minutes', city_page.longest_route_minutes
      ),
      'featured_destinations', COALESCE((
        SELECT jsonb_agg(destination_payload.payload ORDER BY destination_payload.position)
        FROM (
          SELECT
            row_number() OVER (
              ORDER BY
                destination.ranking_score DESC,
                destination_city.name
            ) AS position,
            jsonb_build_object(
              'city', jsonb_build_object(
                'name', destination_city.name,
                'slug', destination_city.slug
              ),
              'country', jsonb_build_object(
                'iso2', destination_country.iso2,
                'name', destination_country.name,
                'slug', destination_country.slug
              ),
              'origin_airports', COALESCE((
                SELECT jsonb_agg(DISTINCT origin_airport.iata ORDER BY origin_airport.iata)
                FROM public.pseo_direct_routes city_route
                JOIN public.airports origin_airport
                  ON origin_airport.id = city_route.origin_airport_id
                WHERE city_route.origin_city_id = destination.origin_city_id
                  AND city_route.destination_city_id = destination.destination_city_id
                  AND city_route.data_version = destination.data_version
              ), '[]'::JSONB),
              'destination_airports', COALESCE((
                SELECT jsonb_agg(DISTINCT destination_airport.iata ORDER BY destination_airport.iata)
                FROM public.pseo_direct_routes city_route
                JOIN public.airports destination_airport
                  ON destination_airport.id = city_route.destination_airport_id
                WHERE city_route.origin_city_id = destination.origin_city_id
                  AND city_route.destination_city_id = destination.destination_city_id
                  AND city_route.data_version = destination.data_version
              ), '[]'::JSONB),
              'airlines', COALESCE((
                SELECT jsonb_agg(DISTINCT airline.iata ORDER BY airline.iata)
                FROM public.pseo_direct_routes city_route
                JOIN public.airlines airline
                  ON airline.id = city_route.operating_airline_id
                WHERE city_route.origin_city_id = destination.origin_city_id
                  AND city_route.destination_city_id = destination.destination_city_id
                  AND city_route.data_version = destination.data_version
              ), '[]'::JSONB),
              'direct_route_count', destination.direct_route_count,
              'frequency_per_week', destination.frequency_per_week,
              'shortest_duration_minutes', destination.shortest_duration_minutes,
              'longest_duration_minutes', destination.longest_duration_minutes,
              'seasonality', destination.seasonality,
              'confidence_score', destination.confidence_score,
              'route_path', format(
                '/flights/%s-to-%s',
                city.slug,
                destination_city.slug
              )
            ) AS payload
          FROM public.city_destination_summaries destination
          JOIN public.cities destination_city
            ON destination_city.id = destination.destination_city_id
          JOIN public.countries destination_country
            ON destination_country.id = destination.destination_country_id
          WHERE destination.origin_city_id = city.id
            AND destination.data_version = v_data_version
          ORDER BY
            destination.ranking_score DESC,
            destination_city.name
          LIMIT v_destination_limit
        ) destination_payload
      ), '[]'::JSONB),
      'direct_countries', COALESCE((
        SELECT jsonb_agg(
          jsonb_build_object(
            'iso2', country_summary.iso2,
            'name', country_summary.name,
            'slug', country_summary.slug,
            'direct_destinations', country_summary.direct_destinations
          )
          ORDER BY
            country_summary.direct_destinations DESC,
            country_summary.name
        )
        FROM (
          SELECT
            destination_country.iso2,
            destination_country.name,
            destination_country.slug,
            count(DISTINCT city_route.destination_city_id) AS direct_destinations
          FROM public.pseo_direct_routes city_route
          JOIN public.countries destination_country
            ON destination_country.id = city_route.destination_country_id
          WHERE city_route.origin_city_id = city.id
            AND city_route.data_version = v_data_version
          GROUP BY destination_country.id
        ) country_summary
      ), '[]'::JSONB),
      'faqs', COALESCE((
        SELECT jsonb_agg(
          jsonb_build_object(
            'question', faq.question,
            'answer', faq.answer,
            'answer_type', faq.answer_type
          )
          ORDER BY faq.display_order
        )
        FROM public.city_page_faqs faq
        WHERE faq.city_page_id = city_page.id
          AND faq.locale = v_locale
          AND faq.status = 'published'
      ), '[]'::JSONB),
      'structured_facts', COALESCE((SELECT jsonb_agg(jsonb_build_object(
        'type',fact.fact_type,'title',fact.title,'body',fact.body,'value',fact.structured_value,
        'source_url',fact.primary_source_url,'last_verified_at',fact.last_verified_at
      ) ORDER BY fact.fact_type) FROM public.city_facts fact WHERE fact.city_id=city.id AND fact.locale=v_locale AND fact.status='published'),'[]'::jsonb),
      'price_summary', jsonb_build_object(
        'state',CASE WHEN EXISTS(SELECT 1 FROM public.route_price_estimates estimate JOIN admin.data_sources source ON source.id=estimate.source_id WHERE estimate.origin_city_id=city.id AND estimate.status='published' AND estimate.valid_until>now() AND source.production_display_allowed AND source.derived_data_allowed) THEN 'available' ELSE 'unavailable' END,
        'reason',CASE WHEN EXISTS(SELECT 1 FROM public.route_price_estimates estimate JOIN admin.data_sources source ON source.id=estimate.source_id WHERE estimate.origin_city_id=city.id AND estimate.status='published' AND estimate.valid_until>now() AND source.production_display_allowed AND source.derived_data_allowed) THEN NULL ELSE 'missing' END,
        'currency_ranges',COALESCE((SELECT jsonb_agg(to_jsonb(price_range)) FROM (SELECT estimate.currency_code,min(estimate.price_min) price_min,max(estimate.price_max) price_max FROM public.route_price_estimates estimate JOIN admin.data_sources source ON source.id=estimate.source_id WHERE estimate.origin_city_id=city.id AND estimate.status='published' AND estimate.valid_until>now() AND source.production_display_allowed AND source.derived_data_allowed GROUP BY estimate.currency_code) price_range),'[]'::jsonb)
      ),
      'internal_link_groups', COALESCE((
        SELECT jsonb_agg(
          jsonb_build_object(
            'cluster', link_group.link_cluster,
            'links', link_group.links
          )
          ORDER BY link_group.cluster_order
        )
        FROM (
          SELECT
            internal_link.link_cluster,
            min(internal_link.display_order) AS cluster_order,
            jsonb_agg(
              jsonb_build_object(
                'title', target_page.display_title,
                'path', target_page.canonical_path,
                'anchor_text', internal_link.anchor_text,
                'secondary_text', internal_link.secondary_text,
                'is_featured', internal_link.is_featured
              )
              ORDER BY
                internal_link.display_order,
                internal_link.relevance_score DESC,
                target_page.canonical_path
            ) AS links
          FROM public.pseo_internal_links internal_link
          JOIN public.pseo_pages target_page
            ON target_page.id = internal_link.target_page_id
          WHERE internal_link.source_page_id = v_pseo_page_id
            AND target_page.status <> 'archived'
          GROUP BY internal_link.link_cluster
        ) link_group
      ), '[]'::JSONB)
    ),
    'meta', jsonb_build_object(
      'canonical_path', pseo_page.canonical_path,
      'is_indexable', city_page.is_indexable,
      'noindex_reason', city_page.noindex_reason,
      'data_version', city_page.data_version,
      'generated_at', city_page.generated_at,
      'source_freshness_at', city_page.source_freshness_at
    ),
    'error', NULL
  )
  INTO v_result
  FROM public.cities city
  JOIN public.countries country
    ON country.id = city.country_id
  JOIN public.city_pages city_page
    ON city_page.id = v_city_page_id
  JOIN public.pseo_pages pseo_page
    ON pseo_page.id = city_page.pseo_page_id
  WHERE city.id = v_city_id;

  RETURN v_result;
END;
$$;

REVOKE ALL ON FUNCTION private.build_city_page_payload(JSONB)
FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION private.build_city_page_payload(JSONB) TO service_role;

-- >>> supabase/sql_src/functions/pseo/airport/build_airport_page_payload.sql

-- ============================================================================
-- Function: private.build_airport_page_payload
-- Feature: Airport Journey pSEO
-- Purpose: Return one frontend-ready airport journey-guide payload.
-- Responsibilities: Compose reviewed journey content, practical airport modules, and provenance.
-- Notes: Verified flights are queried separately through public.rpc_search_routes.
-- ============================================================================

CREATE OR REPLACE FUNCTION private.build_airport_page_payload(p_input JSONB)
RETURNS JSONB
LANGUAGE plpgsql
STABLE
SECURITY INVOKER
SET search_path = ''
AS $$
DECLARE
  v_identity JSONB;
  v_context JSONB;
  v_airport_iata TEXT;
  v_locale TEXT;
  v_airport_id UUID;
  v_airport_page_id UUID;
  v_pseo_page_id UUID;
  v_result JSONB;
BEGIN
  v_identity := private.parse_airport_page_identity(p_input);

  IF v_identity->'error' IS NOT NULL
    AND v_identity->'error' <> 'null'::JSONB
  THEN
    RETURN jsonb_build_object('data', NULL, 'meta', NULL, 'error', v_identity->'error');
  END IF;

  v_airport_iata := v_identity #>> '{data,airport_iata}';
  v_locale := v_identity #>> '{data,locale}';
  v_context := private.resolve_airport_page_context(v_airport_iata, v_locale);

  IF v_context->'error' IS NOT NULL
    AND v_context->'error' <> 'null'::JSONB
  THEN
    RETURN jsonb_build_object('data', NULL, 'meta', NULL, 'error', v_context->'error');
  END IF;

  v_airport_id := (v_context #>> '{data,airport_id}')::UUID;
  v_airport_page_id := (v_context #>> '{data,airport_page_id}')::UUID;
  v_pseo_page_id := (v_context #>> '{data,pseo_page_id}')::UUID;

  SELECT jsonb_build_object(
    'data', jsonb_build_object(
      'airport', jsonb_build_object(
        'id', airport.id,
        'iata', airport.iata,
        'icao', airport.icao,
        'name', airport.name,
        'slug', airport.slug,
        'image_path', airport.image_path,
        'type', airport.airport_type,
        'timezone', airport.timezone,
        'latitude', airport.latitude,
        'longitude', airport.longitude,
        'city', jsonb_build_object('id', city.id, 'name', city.name, 'slug', city.slug),
        'country', jsonb_build_object(
          'id', country.id,
          'code', country.iso2,
          'name', country.name,
          'slug', country.slug
        )
      ),
      'seo', jsonb_build_object(
        'h1', airport_page.h1,
        'subheadline', airport_page.subheadline,
        'title', airport_page.seo_title,
        'meta_description', airport_page.meta_description,
        'og_title', airport_page.og_title,
        'og_description', airport_page.og_description,
        'og_image_path', airport_page.og_image_path
      ),
      'orientation', jsonb_build_object(
        'intro', airport_page.intro,
        'summary', airport_page.orientation_summary,
        'primary_city_area_label', airport_page.primary_city_area_label,
        'city_distance_km', airport_page.city_distance_km,
        'terminal_count', (
          SELECT count(*)::INTEGER
          FROM public.airport_terminals terminal
          WHERE terminal.airport_id = v_airport_id
            AND terminal.status = 'active'
        )
      ),
      'quick_answers', jsonb_build_object(
        'default_transport', (
          SELECT jsonb_build_object(
            'name', access.name,
            'typical_minutes', jsonb_build_object(
              'min', access.duration_min_minutes,
              'max', access.duration_max_minutes
            ),
            'estimated_price', jsonb_build_object(
              'min', access.price_min,
              'max', access.price_max,
              'currency', access.currency_code
            ),
            'last_verified_at', access.last_verified_at
          )
          FROM public.airport_access_options access
          WHERE access.airport_page_id = v_airport_page_id
            AND access.status = 'published'
            AND access.journey_direction IN ('from_airport', 'both')
          ORDER BY access.display_order
          LIMIT 1
        ),
        'city_distance_km', airport_page.city_distance_km,
        'terminal_count', (
          SELECT count(*)::INTEGER
          FROM public.airport_terminals terminal
          WHERE terminal.airport_id = v_airport_id
            AND terminal.status = 'active'
        )
      ),
      'arrival', jsonb_build_object(
        'summary', airport_page.arrival_summary,
        'steps', COALESCE((
          SELECT jsonb_agg(
            jsonb_build_object(
              'audience', step.audience,
              'title', step.title,
              'body', step.body,
              'source_url', step.primary_source_url,
              'last_verified_at', step.last_verified_at
            )
            ORDER BY step.audience, step.display_order
          )
          FROM public.airport_journey_steps step
          WHERE step.airport_page_id = v_airport_page_id
            AND step.locale = v_locale
            AND step.journey_type = 'arrival'
            AND step.status = 'published'
        ), '[]'::JSONB)
      ),
      'departure', jsonb_build_object(
        'summary', airport_page.departure_summary,
        'steps', COALESCE((
          SELECT jsonb_agg(
            jsonb_build_object(
              'audience', step.audience,
              'title', step.title,
              'body', step.body,
              'source_url', step.primary_source_url,
              'last_verified_at', step.last_verified_at
            )
            ORDER BY step.audience, step.display_order
          )
          FROM public.airport_journey_steps step
          WHERE step.airport_page_id = v_airport_page_id
            AND step.locale = v_locale
            AND step.journey_type = 'departure'
            AND step.status = 'published'
        ), '[]'::JSONB)
      ),
      'transport', COALESCE((
        SELECT jsonb_agg(
          jsonb_build_object(
            'direction', access.journey_direction,
            'type', access.access_type,
            'name', access.name,
            'destination_label', access.destination_label,
            'summary', access.summary,
            'duration', jsonb_build_object(
              'min_minutes', access.duration_min_minutes,
              'max_minutes', access.duration_max_minutes
            ),
            'estimated_price', jsonb_build_object(
              'min', access.price_min,
              'max', access.price_max,
              'currency', access.currency_code
            ),
            'operating_hours_summary', access.operating_hours_summary,
            'pickup_location_summary', access.pickup_location_summary,
            'best_for_label', access.best_for_label,
            'luggage_summary', access.luggage_summary,
            'accessibility_summary', access.accessibility_summary,
            'booking_url', access.booking_url,
            'source_url', access.primary_source_url,
            'last_verified_at', access.last_verified_at
          )
          ORDER BY access.display_order
        )
        FROM public.airport_access_options access
        WHERE access.airport_page_id = v_airport_page_id
          AND access.status = 'published'
      ), '[]'::JSONB),
      'parking', (
        SELECT to_jsonb(parking)
          - 'id'
          - 'airport_page_id'
          - 'created_at'
          - 'updated_at'
          - 'status'
        FROM public.airport_parking_information parking
        WHERE parking.airport_page_id = v_airport_page_id
          AND parking.status = 'published'
      ),
      'terminals', COALESCE((
        SELECT jsonb_agg(
          jsonb_build_object(
            'code', terminal.code,
            'name', terminal.name,
            'status', terminal.status
          )
          ORDER BY terminal.code
        )
        FROM public.airport_terminals terminal
        WHERE terminal.airport_id = v_airport_id
      ), '[]'::JSONB),
      'facilities', COALESCE((
        SELECT jsonb_agg(
          jsonb_build_object(
            'category', facility.category,
            'name', facility.name,
            'summary', facility.summary,
            'operating_hours', facility.operating_hours,
            'source_url', facility.primary_source_url,
            'last_verified_at', facility.last_verified_at
          )
          ORDER BY facility.display_order
        )
        FROM public.airport_facilities facility
        WHERE facility.airport_id = v_airport_id
          AND facility.locale = v_locale
          AND facility.status = 'published'
      ), '[]'::JSONB),
      'lounges', COALESCE((
        SELECT jsonb_agg(
          jsonb_build_object(
            'name', lounge.name,
            'location_summary', lounge.location_summary,
            'location_type', lounge.location_type,
            'access_summary', lounge.access_summary,
            'amenities', to_jsonb(lounge.amenities),
            'official_url', lounge.official_url,
            'source_url', lounge.primary_source_url,
            'last_verified_at', lounge.last_verified_at
          )
          ORDER BY lounge.display_order
        )
        FROM public.airport_lounges lounge
        WHERE lounge.airport_page_id = v_airport_page_id
          AND lounge.status = 'published'
      ), '[]'::JSONB),
      'notices', COALESCE((
        SELECT jsonb_agg(to_jsonb(notice) - 'id' - 'airport_page_id' - 'created_at' - 'updated_at' - 'status' ORDER BY notice.display_order)
        FROM public.airport_page_notices notice
        WHERE notice.airport_page_id = v_airport_page_id
          AND notice.status = 'published'
      ), '[]'::JSONB),
      'faqs', COALESCE((
        SELECT jsonb_agg(
          jsonb_build_object(
            'question', faq.question,
            'answer', faq.answer,
            'answer_type', faq.answer_type
          )
          ORDER BY faq.display_order
        )
        FROM public.airport_page_faqs faq
        WHERE faq.airport_page_id = v_airport_page_id
          AND faq.locale = v_locale
          AND faq.status = 'published'
      ), '[]'::JSONB),
      'internal_link_groups', COALESCE((
        SELECT jsonb_agg(
          jsonb_build_object('cluster', links.link_cluster, 'links', links.items)
          ORDER BY links.link_cluster
        )
        FROM (
          SELECT
            link.link_cluster,
            jsonb_agg(
              jsonb_build_object(
                'anchor_text', link.anchor_text,
                'secondary_text', link.secondary_text,
                'path', target.canonical_path
              )
              ORDER BY link.display_order
            ) AS items
          FROM public.pseo_internal_links link
          JOIN public.pseo_pages target
            ON target.id = link.target_page_id
          WHERE link.source_page_id = v_pseo_page_id
            AND target.status = 'published'
          GROUP BY link.link_cluster
        ) links
      ), '[]'::JSONB),
      'provenance', jsonb_build_object(
        'last_editorial_review', airport_page.content_reviewed_at,
        'source_freshness_at', airport_page.source_freshness_at,
        'routes_refreshed_at', airport_page.route_data_refreshed_at,
        'data_version', airport_page.data_version,
        'estimates_are_live', FALSE
      )
    ),
    'meta', jsonb_build_object(
      'canonical_path', pseo_page.canonical_path,
      'is_indexable', airport_page.is_indexable,
      'noindex_reason', airport_page.noindex_reason,
      'data_version', airport_page.data_version,
      'source_freshness_at', airport_page.source_freshness_at,
      'generated_at', airport_page.generated_at
    ),
    'error', NULL
  )
  INTO v_result
  FROM public.airport_pages airport_page
  JOIN public.pseo_pages pseo_page
    ON pseo_page.id = airport_page.pseo_page_id
  JOIN public.airports airport
    ON airport.id = airport_page.airport_id
  LEFT JOIN public.cities city
    ON city.id = airport.city_id
  JOIN public.countries country
    ON country.id = airport.country_id
  WHERE airport_page.id = v_airport_page_id;

  RETURN v_result;
END;
$$;

REVOKE ALL ON FUNCTION private.build_airport_page_payload(JSONB)
FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION private.build_airport_page_payload(JSONB) TO service_role;

-- >>> supabase/sql_src/functions/pseo/shared/resolve_route_price_estimate.sql

-- Resolve a display-safe estimate or an explicit null-state. Never substitutes zero.
CREATE OR REPLACE FUNCTION public.resolve_route_price_estimate(
  p_origin_city_id UUID,p_destination_city_id UUID,p_cabin TEXT DEFAULT 'any',p_stop_bucket TEXT DEFAULT 'any'
) RETURNS JSONB LANGUAGE plpgsql STABLE SET search_path='' AS $$
DECLARE v_row RECORD; v_any RECORD;
BEGIN
  SELECT estimate.*,source.production_display_allowed,source.derived_data_allowed,
    source.rights_effective_at,source.rights_expires_at,source.attribution_text,source.attribution_url
  INTO v_any FROM public.route_price_estimates estimate
  JOIN admin.data_sources source ON source.id=estimate.source_id
  WHERE estimate.origin_city_id=p_origin_city_id AND estimate.destination_city_id=p_destination_city_id
    AND estimate.cabin IN (p_cabin,'any') AND estimate.stop_bucket IN (p_stop_bucket,'any')
  ORDER BY estimate.last_verified_at DESC LIMIT 1;
  IF v_any.id IS NULL THEN RETURN jsonb_build_object('state','unavailable','reason','missing','estimate',NULL); END IF;
  IF NOT v_any.production_display_allowed OR NOT v_any.derived_data_allowed
    OR (v_any.rights_effective_at IS NOT NULL AND now() NOT BETWEEN v_any.rights_effective_at AND v_any.rights_expires_at)
  THEN RETURN jsonb_build_object('state','unavailable','reason','unlicensed','estimate',NULL); END IF;
  IF v_any.status <> 'published' OR v_any.valid_until <= now()
  THEN RETURN jsonb_build_object('state','unavailable','reason','expired','estimate',NULL); END IF;
  v_row := v_any;
  RETURN jsonb_build_object('state','available','reason',NULL,'estimate',jsonb_build_object(
    'price_min',v_row.price_min,'price_max',v_row.price_max,'currency_code',v_row.currency_code,
    'trip_type',v_row.trip_type,'cabin',v_row.cabin,'stop_bucket',v_row.stop_bucket,
    'baggage_included',v_row.baggage_included,'method',v_row.estimate_method,
    'confidence_score',v_row.confidence_score,'last_verified_at',v_row.last_verified_at,
    'valid_until',v_row.valid_until,'attribution_text',v_row.attribution_text,'attribution_url',v_row.attribution_url
  ));
END;
$$;
REVOKE ALL ON FUNCTION public.resolve_route_price_estimate(UUID,UUID,TEXT,TEXT) FROM public,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.resolve_route_price_estimate(UUID,UUID,TEXT,TEXT) TO service_role;

-- >>> supabase/sql_src/functions/pseo/homepage/rpc_search_places.sql

CREATE OR REPLACE FUNCTION public.rpc_search_places(p_input JSONB) RETURNS JSONB LANGUAGE plpgsql STABLE SET search_path='' AS $$
DECLARE v_query TEXT;v_locale TEXT:=COALESCE(NULLIF(p_input->>'locale',''),'en-GB');v_limit INTEGER:=COALESCE((p_input->>'limit')::int,8);BEGIN
v_query:=lower(btrim(COALESCE(p_input->>'query','')));IF char_length(v_query)<1 OR v_limit NOT BETWEEN 1 AND 20 THEN RETURN private.build_rpc_error(NULL,'ERR_INVALID_REQUEST','Invalid place search.');END IF;
RETURN jsonb_build_object('data',COALESCE((SELECT jsonb_agg(to_jsonb(result) ORDER BY result.rank_score DESC,result.name) FROM(
SELECT 'city' entity_type,city.id,city.name,city.slug code,city.slug,CASE WHEN city.slug=v_query THEN 2 ELSE 1 END rank_score FROM public.cities city WHERE lower(city.name) LIKE '%'||v_query||'%' OR city.slug LIKE '%'||v_query||'%'
UNION ALL SELECT 'airport',airport.id,airport.name,airport.iata,airport.slug,CASE WHEN lower(airport.iata)=v_query THEN 2 ELSE 1 END FROM public.airports airport WHERE lower(airport.name) LIKE '%'||v_query||'%' OR lower(airport.iata) LIKE v_query||'%'
UNION ALL SELECT 'metro_area',metro.id,metro.name,metro.code,metro.slug,CASE WHEN lower(metro.code)=v_query THEN 2 ELSE 1 END FROM public.metro_areas metro WHERE lower(metro.name) LIKE '%'||v_query||'%' OR lower(metro.code) LIKE v_query||'%'
UNION ALL SELECT alias.entity_type,alias.entity_id,alias.alias,NULL,NULL,1.5 FROM public.place_aliases alias WHERE alias.locale=v_locale AND alias.normalized_alias LIKE '%'||v_query||'%'
)result LIMIT v_limit),'[]'::jsonb),'meta',jsonb_build_object('query',v_query,'locale',v_locale,'limit',v_limit),'error',NULL);
END;$$;
REVOKE ALL ON FUNCTION public.rpc_search_places(JSONB) FROM public,anon,authenticated;GRANT EXECUTE ON FUNCTION public.rpc_search_places(JSONB) TO service_role;

-- >>> supabase/sql_src/functions/pseo/homepage/rpc_resolve_homepage_origin.sql

-- ============================================================================
-- Function: public.rpc_resolve_homepage_origin
-- Feature: Homepage Discovery
-- Purpose: Resolve the nearest route-capable airport from visitor coordinates.
-- Responsibilities: Validate coordinates, rank eligible airports, and fall back to JFK.
-- Notes: Raw IP addresses never enter this function or the database.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.rpc_resolve_homepage_origin(p_input JSONB)
RETURNS JSONB
LANGUAGE plpgsql
STABLE
SECURITY INVOKER
SET search_path = ''
AS $$
DECLARE
  ------------------------------------------------------------------
  -- Input
  ------------------------------------------------------------------
  v_latitude DOUBLE PRECISION;
  v_longitude DOUBLE PRECISION;
  v_has_valid_coordinates BOOLEAN := FALSE;

  ------------------------------------------------------------------
  -- Resolved origin
  ------------------------------------------------------------------
  v_airport RECORD;
  v_resolution TEXT := 'fallback';
BEGIN
  -- STEP 01: Accept only finite, bounded numeric coordinate pairs.
  IF jsonb_typeof(p_input) = 'object'
    AND jsonb_typeof(p_input -> 'latitude') = 'number'
    AND jsonb_typeof(p_input -> 'longitude') = 'number'
  THEN
    v_latitude := (p_input ->> 'latitude')::DOUBLE PRECISION;
    v_longitude := (p_input ->> 'longitude')::DOUBLE PRECISION;
    v_has_valid_coordinates := v_latitude BETWEEN -90 AND 90
      AND v_longitude BETWEEN -180 AND 180;
  END IF;

  -- STEP 02: Rank active airports that can actually originate a route.
  IF v_has_valid_coordinates THEN
    SELECT
      airport.iata,
      airport.name,
      airport.latitude,
      airport.longitude,
      city.name AS city_name,
      city.slug AS city_slug,
      6371 * acos(
        LEAST(
          1,
          GREATEST(
            -1,
            cos(radians(v_latitude))
              * cos(radians(airport.latitude))
              * cos(radians(airport.longitude) - radians(v_longitude))
              + sin(radians(v_latitude))
              * sin(radians(airport.latitude))
          )
        )
      ) AS distance_km,
      (
        SELECT count(*)::INTEGER
        FROM public.route_options route_option
        WHERE route_option.origin_airport_id = airport.id
      ) AS route_count
    INTO v_airport
    FROM public.airports airport
    JOIN public.cities city
      ON city.id = airport.city_id
    WHERE airport.status = 'active'
      AND airport.iata IS NOT NULL
      AND airport.latitude IS NOT NULL
      AND airport.longitude IS NOT NULL
      AND EXISTS (
        SELECT 1
        FROM public.route_options route_option
        WHERE route_option.origin_airport_id = airport.id
      )
    ORDER BY distance_km, airport.iata
    LIMIT 1;

    IF FOUND THEN
      v_resolution := 'nearest';
    END IF;
  END IF;

  -- STEP 03: Use the explicit JFK fallback when geolocation cannot resolve.
  IF v_resolution = 'fallback' THEN
    SELECT
      airport.iata,
      airport.name,
      airport.latitude,
      airport.longitude,
      city.name AS city_name,
      city.slug AS city_slug,
      NULL::DOUBLE PRECISION AS distance_km,
      (
        SELECT count(*)::INTEGER
        FROM public.route_options route_option
        WHERE route_option.origin_airport_id = airport.id
      ) AS route_count
    INTO v_airport
    FROM public.airports airport
    LEFT JOIN public.cities city
      ON city.id = airport.city_id
    WHERE airport.iata = 'JFK';
  END IF;

  RETURN jsonb_build_object(
    'data', jsonb_build_object(
      'airport', jsonb_build_object(
        'iata', COALESCE(v_airport.iata, 'JFK'),
        'name', v_airport.name,
        'latitude', v_airport.latitude,
        'longitude', v_airport.longitude
      ),
      'city', CASE
        WHEN v_airport.city_slug IS NULL THEN NULL
        ELSE jsonb_build_object(
          'name', v_airport.city_name,
          'slug', v_airport.city_slug
        )
      END,
      'distance_km', CASE
        WHEN v_airport.distance_km IS NULL THEN NULL
        ELSE round(v_airport.distance_km::NUMERIC, 1)
      END,
      'route_count', COALESCE(v_airport.route_count, 0)
    ),
    'meta', jsonb_build_object(
      'resolution', v_resolution,
      'fallback_iata', 'JFK',
      'fallback_data_available', v_airport.iata = 'JFK'
    ),
    'error', NULL
  );
END;
$$;

REVOKE ALL ON FUNCTION public.rpc_resolve_homepage_origin(JSONB)
FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_resolve_homepage_origin(JSONB) TO service_role;

-- >>> supabase/sql_src/functions/pseo/homepage/build_homepage_discovery.sql

CREATE OR REPLACE FUNCTION private.build_homepage_discovery(p_input JSONB)
RETURNS JSONB LANGUAGE plpgsql STABLE SET search_path='' AS $$
DECLARE
  v_origin TEXT:=upper(btrim(COALESCE(p_input->>'origin','')));
  v_max_stops INTEGER:=COALESCE((p_input->>'max_stops')::INTEGER,3);
  v_max_duration INTEGER:=NULLIF(p_input->>'max_duration_minutes','')::INTEGER;
  v_price_max NUMERIC:=NULLIF(p_input->>'price_max','')::NUMERIC;
  v_currency TEXT:=upper(NULLIF(btrim(COALESCE(p_input->>'currency','')),''));
  v_limit INTEGER:=COALESCE((p_input->>'limit')::INTEGER,20);
  v_offset INTEGER:=COALESCE((p_input->>'offset')::INTEGER,0);
  v_airlines TEXT[]:='{}';v_connections TEXT[]:='{}';v_origin_airports UUID[];
BEGIN
  IF v_max_stops NOT BETWEEN 0 AND 3 OR v_limit NOT BETWEEN 1 AND 100 OR v_offset NOT BETWEEN 0 AND 10000
    OR v_max_duration IS NOT NULL AND v_max_duration<1 OR v_price_max IS NOT NULL AND v_price_max<0
    OR v_currency IS NOT NULL AND v_currency!~'^[A-Z]{3}$'
  THEN RETURN private.build_rpc_error(NULL,'ERR_INVALID_REQUEST','Invalid homepage discovery filters.');END IF;
  IF p_input?'airlines' THEN SELECT COALESCE(array_agg(upper(value)),'{}') INTO v_airlines FROM jsonb_array_elements_text(p_input->'airlines');END IF;
  IF p_input?'connection_airports' THEN SELECT COALESCE(array_agg(upper(value)),'{}') INTO v_connections FROM jsonb_array_elements_text(p_input->'connection_airports');END IF;
  IF EXISTS(SELECT 1 FROM unnest(v_airlines) x WHERE x!~'^[A-Z0-9]{2}$') OR EXISTS(SELECT 1 FROM unnest(v_connections) x WHERE x!~'^[A-Z0-9]{3}$') THEN RETURN private.build_rpc_error(NULL,'ERR_INVALID_REQUEST','Invalid code filter.');END IF;
  SELECT array_agg(DISTINCT airport.id) INTO v_origin_airports FROM public.airports airport
  LEFT JOIN public.cities city ON city.id=airport.city_id LEFT JOIN public.metro_area_airports mapping ON mapping.airport_id=airport.id LEFT JOIN public.metro_areas metro ON metro.id=mapping.metro_area_id
  WHERE airport.iata=v_origin OR upper(city.slug)=v_origin OR metro.code=v_origin;
  RETURN jsonb_build_object('data',jsonb_build_object(
    'featured_origins',(SELECT COALESCE(jsonb_agg(to_jsonb(item)),'[]') FROM(SELECT city.name,city.slug,count(option.id)::INTEGER route_option_count FROM public.cities city JOIN public.airports airport ON airport.city_id=city.id JOIN public.route_options option ON option.origin_airport_id=airport.id GROUP BY city.id ORDER BY count(option.id) DESC,city.name LIMIT 12)item),
    'route_map',COALESCE((SELECT jsonb_agg(payload ORDER BY stop_count,total_duration_minutes) FROM(
      SELECT option.stop_count,option.total_duration_minutes,jsonb_build_object('route_option_id',option.id,'from',origin.iata,'to',destination.iata,'stops',option.stop_count,'duration_minutes',option.total_duration_minutes,
        'connection_airports',(SELECT COALESCE(jsonb_agg(airport.iata ORDER BY leg.ordinality),'[]') FROM unnest(option.connection_airport_ids) WITH ORDINALITY leg(id,ordinality) JOIN public.airports airport ON airport.id=leg.id),
        'route_path',format('/flights/%s-to-%s',origin_city.slug,destination_city.slug),
        'price',public.resolve_route_price_estimate(origin_city.id,destination_city.id,'any',CASE option.stop_count WHEN 0 THEN 'direct' WHEN 1 THEN 'one_stop' WHEN 2 THEN 'two_stops' ELSE 'three_stops' END)) payload
      FROM public.route_options option JOIN public.airports origin ON origin.id=option.origin_airport_id JOIN public.cities origin_city ON origin_city.id=origin.city_id JOIN public.airports destination ON destination.id=option.destination_airport_id JOIN public.cities destination_city ON destination_city.id=destination.city_id
      WHERE (v_origin_airports IS NULL OR option.origin_airport_id=ANY(v_origin_airports)) AND option.stop_count<=v_max_stops
        AND (v_max_duration IS NULL OR option.total_duration_minutes<=v_max_duration)
        AND (cardinality(v_airlines)=0 OR EXISTS(SELECT 1 FROM unnest(option.operating_airline_ids) leg_id(id) JOIN public.airlines airline ON airline.id=leg_id.id WHERE airline.iata=ANY(v_airlines)))
        AND (cardinality(v_connections)=0 OR EXISTS(SELECT 1 FROM unnest(option.connection_airport_ids) connection_id(id) JOIN public.airports airport ON airport.id=connection_id.id WHERE airport.iata=ANY(v_connections)))
        AND (v_price_max IS NULL OR EXISTS(SELECT 1 FROM public.route_price_estimates estimate JOIN admin.data_sources source ON source.id=estimate.source_id WHERE estimate.origin_city_id=origin_city.id AND estimate.destination_city_id=destination_city.id AND estimate.status='published' AND estimate.valid_until>now() AND source.production_display_allowed AND source.derived_data_allowed AND estimate.price_min<=v_price_max AND (v_currency IS NULL OR estimate.currency_code=v_currency)))
      ORDER BY option.stop_count,option.total_duration_minutes LIMIT v_limit OFFSET v_offset
    )filtered),'[]'),
    'nearby_airports',COALESCE((SELECT jsonb_agg(jsonb_build_object('iata',nearby.iata,'distance_km',mapping.distance_km)) FROM public.nearby_airports mapping JOIN public.airports nearby ON nearby.id=mapping.nearby_airport_id WHERE mapping.airport_id=ANY(COALESCE(v_origin_airports,'{}'))),'[]')),
    'meta',jsonb_build_object('data_version',(SELECT data_version FROM public.route_options ORDER BY generated_at DESC LIMIT 1),'max_supported_stops',3,'limit',v_limit,'offset',v_offset,'facets',jsonb_build_object(
      'stops',(SELECT COALESCE(jsonb_agg(to_jsonb(x)),'[]') FROM(SELECT stop_count value,count(*)::INTEGER count FROM public.route_options WHERE (v_origin_airports IS NULL OR origin_airport_id=ANY(v_origin_airports)) GROUP BY stop_count ORDER BY stop_count)x),
      'airlines',(SELECT COALESCE(jsonb_agg(to_jsonb(x) ORDER BY x.value),'[]') FROM(SELECT airline.iata value,count(*)::INTEGER count FROM public.route_options option CROSS JOIN LATERAL unnest(option.operating_airline_ids) leg_id(id) JOIN public.airlines airline ON airline.id=leg_id.id WHERE (v_origin_airports IS NULL OR option.origin_airport_id=ANY(v_origin_airports)) GROUP BY airline.iata)x),
      'connections',(SELECT COALESCE(jsonb_agg(to_jsonb(x) ORDER BY x.value),'[]') FROM(SELECT airport.iata value,count(*)::INTEGER count FROM public.route_options option CROSS JOIN LATERAL unnest(option.connection_airport_ids) connection_id(id) JOIN public.airports airport ON airport.id=connection_id.id WHERE (v_origin_airports IS NULL OR option.origin_airport_id=ANY(v_origin_airports)) GROUP BY airport.iata)x),
      'price',jsonb_build_object('currency',v_currency,'max',v_price_max,'missing_is_zero',FALSE))),'error',NULL);
END;$$;
REVOKE ALL ON FUNCTION private.build_homepage_discovery(JSONB) FROM public,anon,authenticated;GRANT EXECUTE ON FUNCTION private.build_homepage_discovery(JSONB) TO service_role;

-- >>> supabase/sql_src/functions/pseo/route/build_route_page_payload.sql

-- ============================================================================
-- Function: private.build_route_page_payload
-- Purpose: Compose one reviewed route page during read-model publication.
-- Responsibilities: Join canonical identities, route options, editorial modules and FAQs.
-- ============================================================================

CREATE OR REPLACE FUNCTION private.build_route_page_payload(p_input JSONB)
RETURNS JSONB
LANGUAGE plpgsql
STABLE
SET search_path = ''
AS $$
DECLARE
  v_locale TEXT := COALESCE(NULLIF(p_input->>'locale', ''), 'en-GB');
  v_page public.route_pages%ROWTYPE;
  v_pseo public.pseo_pages%ROWTYPE;
  v_origin_slug TEXT;
  v_destination_slug TEXT;
BEGIN
  SELECT page.*
  INTO v_page
  FROM public.route_pages page
  WHERE page.canonical_slug = lower(p_input->>'route_slug')
    AND page.locale = v_locale;

  IF v_page.id IS NULL THEN
    RETURN private.build_rpc_error(NULL, 'ERR_NOT_FOUND', 'Route page not found.');
  END IF;

  SELECT page.*
  INTO v_pseo
  FROM public.pseo_pages page
  WHERE page.id = v_page.pseo_page_id;

  SELECT city.slug
  INTO v_origin_slug
  FROM public.cities city
  WHERE city.id = v_page.origin_city_id;

  SELECT city.slug
  INTO v_destination_slug
  FROM public.cities city
  WHERE city.id = v_page.destination_city_id;

  RETURN jsonb_build_object(
    'data', jsonb_build_object(
      'route', jsonb_build_object(
        'origin', (
          SELECT jsonb_build_object('name', city.name, 'slug', city.slug)
          FROM public.cities city
          WHERE city.id = v_page.origin_city_id
        ),
        'destination', (
          SELECT jsonb_build_object('name', city.name, 'slug', city.slug)
          FROM public.cities city
          WHERE city.id = v_page.destination_city_id
        )
      ),
      'seo', jsonb_build_object(
        'h1', v_page.h1,
        'subheadline', v_page.subheadline,
        'title', v_page.seo_title,
        'meta_description', v_page.meta_description,
        'intro', v_page.intro
      ),
      'summary', jsonb_build_object(
        'direct_options', v_page.direct_option_count,
        'indirect_options', v_page.indirect_option_count,
        'fastest_direct_minutes', v_page.fastest_direct_minutes,
        'fastest_indirect_minutes', v_page.fastest_indirect_minutes
      ),
      'options', public.rpc_search_routes(jsonb_build_object(
        'scope', jsonb_build_object(
          'type', 'city_pair',
          'from', v_origin_slug,
          'to', v_destination_slug
        ),
        'filters', jsonb_build_object('max_stops', 3),
        'page_size', 20
      ))->'data',
      'price', public.resolve_route_price_estimate(
        v_page.origin_city_id,
        v_page.destination_city_id,
        'any',
        'any'
      ),
      'airport_comparison', COALESCE((
        SELECT jsonb_agg(
          jsonb_build_object(
            'endpoint_role', comparison.endpoint_role,
            'airport_iata', airport.iata,
            'summary', comparison.transfer_summary,
            'duration_min_minutes', comparison.duration_min_minutes,
            'duration_max_minutes', comparison.duration_max_minutes,
            'price_min', comparison.price_min,
            'price_max', comparison.price_max,
            'currency_code', comparison.currency_code,
            'source_url', comparison.primary_source_url
          )
          ORDER BY comparison.display_order
        )
        FROM public.route_page_airport_comparisons comparison
        JOIN public.airports airport
          ON airport.id = comparison.airport_id
        WHERE comparison.route_page_id = v_page.id
          AND comparison.status = 'published'
      ), '[]'::JSONB),
      'travel_facts', COALESCE((
        SELECT jsonb_agg(
          to_jsonb(fact) - 'route_page_id'
          ORDER BY fact.display_order
        )
        FROM public.route_page_travel_facts fact
        WHERE fact.route_page_id = v_page.id
          AND fact.locale = v_locale
          AND fact.status = 'published'
      ), '[]'::JSONB),
      'editorial_sections', COALESCE((
        SELECT jsonb_agg(
          to_jsonb(section) - 'route_page_id'
          ORDER BY section.display_order
        )
        FROM public.route_page_editorial_sections section
        WHERE section.route_page_id = v_page.id
          AND section.locale = v_locale
          AND section.status = 'published'
      ), '[]'::JSONB),
      'faqs', COALESCE((
        SELECT jsonb_agg(
          jsonb_build_object(
            'question', faq.question,
            'answer', faq.answer,
            'answer_type', faq.answer_type,
            'source_url', faq.primary_source_url,
            'last_verified_at', faq.last_verified_at
          )
          ORDER BY faq.display_order
        )
        FROM public.route_page_faqs faq
        WHERE faq.route_page_id = v_page.id
          AND faq.locale = v_locale
          AND faq.status = 'published'
      ), '[]'::JSONB),
      'unknowns', jsonb_build_object(
        'self_transfer', 'unknown',
        'through_baggage', 'unknown',
        'fare_rules', 'unknown',
        'live_availability', 'unknown'
      ),
      'affiliate', jsonb_build_object(
        'offers', jsonb_build_array(),
        'disclosure', 'Some outbound links may become affiliate links when approved partners are configured. No booking or live fare is currently claimed.'
      )
    ),
    'meta', jsonb_build_object(
      'canonical_path', v_pseo.canonical_path,
      'is_indexable', v_page.is_indexable,
      'noindex_reason', v_page.noindex_reason,
      'data_version', v_page.data_version,
      'source_freshness_at', v_page.source_freshness_at
    ),
    'error', NULL
  );
END;
$$;

REVOKE ALL ON FUNCTION private.build_route_page_payload(JSONB)
FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION private.build_route_page_payload(JSONB) TO service_role;

-- >>> supabase/sql_src/functions/pseo/shared/rpc_get_sitemap.sql

CREATE OR REPLACE FUNCTION public.rpc_get_sitemap(p_input JSONB DEFAULT '{}'::JSONB) RETURNS JSONB LANGUAGE sql STABLE SET search_path='' AS $$
SELECT jsonb_build_object('data',COALESCE(jsonb_agg(jsonb_build_object('path',page.canonical_path,'locale',page.locale,'page_type',page.page_type,'last_modified',page.content_updated_at) ORDER BY page.canonical_path),'[]'::jsonb),'meta',jsonb_build_object('only_indexable',TRUE),'error',NULL)
FROM public.pseo_pages page WHERE page.status='published' AND page.is_indexable AND page.noindex_reason IS NULL AND (NOT p_input?'locale' OR page.locale=p_input->>'locale');
$$;
REVOKE ALL ON FUNCTION public.rpc_get_sitemap(JSONB) FROM public,anon,authenticated;GRANT EXECUTE ON FUNCTION public.rpc_get_sitemap(JSONB) TO service_role;

-- >>> supabase/sql_src/functions/pseo/shared/refresh_page_read_models.sql

-- ============================================================================
-- Function: private.refresh_page_read_models
-- Purpose: Materialize all page-specific single-load read models for one candidate version.
-- Responsibilities: Compose bounded page payloads outside the public request path.
-- Notes: Private builders compose bounded modules only during publication.
-- ============================================================================

CREATE OR REPLACE FUNCTION private.refresh_page_read_models(p_publication_version_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
VOLATILE
SET search_path = ''
AS $$
DECLARE
  v_homepage_count INTEGER;
  v_city_count INTEGER;
  v_airport_count INTEGER;
  v_route_count INTEGER;
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.publication_versions version
    WHERE version.id = p_publication_version_id
      AND version.status = 'building'
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'ERR_PUBLICATION_VERSION_INVALID';
  END IF;

  DELETE FROM public.homepage_read_models WHERE publication_version_id = p_publication_version_id;
  DELETE FROM public.city_page_read_models WHERE publication_version_id = p_publication_version_id;
  DELETE FROM public.airport_page_read_models WHERE publication_version_id = p_publication_version_id;
  DELETE FROM public.route_page_read_models WHERE publication_version_id = p_publication_version_id;

  INSERT INTO public.homepage_read_models (publication_version_id, locale, payload)
  SELECT
    p_publication_version_id,
    homepage.locale,
    jsonb_build_object(
      'page', jsonb_build_object('type', 'homepage', 'locale', homepage.locale),
      'seo', jsonb_build_object(
        'h1', homepage.h1,
        'subheadline', homepage.subheadline,
        'intro', homepage.intro,
        'title', homepage.seo_title,
        'meta_description', homepage.meta_description
      ),
      'facts', jsonb_build_object(),
      'discovery', private.build_homepage_discovery(jsonb_build_object(
        'origin', 'GLOBAL',
        'max_stops', 0,
        'limit', 20
      ))->'data',
      'content', jsonb_build_object(
        'sections', COALESCE((
          SELECT jsonb_agg(to_jsonb(section) - 'homepage_page_id' ORDER BY section.display_order)
          FROM public.homepage_content_sections section
          WHERE section.homepage_page_id = homepage.id
            AND section.locale = homepage.locale
            AND section.status = 'published'
        ), '[]'::JSONB),
        'featured_origins', COALESCE((
          SELECT jsonb_agg(to_jsonb(origin) - 'homepage_page_id' ORDER BY origin.display_order)
          FROM public.homepage_featured_origins origin
          WHERE origin.homepage_page_id = homepage.id
            AND origin.status = 'published'
        ), '[]'::JSONB),
        'featured_routes', COALESCE((
          SELECT jsonb_agg(to_jsonb(route) - 'homepage_page_id' ORDER BY route.display_order)
          FROM public.homepage_featured_routes route
          WHERE route.homepage_page_id = homepage.id
            AND route.status = 'published'
        ), '[]'::JSONB)
      ),
      'faqs', COALESCE((
        SELECT jsonb_agg(to_jsonb(faq) - 'homepage_page_id' ORDER BY faq.display_order)
        FROM public.homepage_faqs faq
        WHERE faq.homepage_page_id = homepage.id
          AND faq.locale = homepage.locale
          AND faq.status = 'published'
      ), '[]'::JSONB),
      'internal_links', '[]'::JSONB,
      'indexability', jsonb_build_object(
        'is_indexable', homepage.is_indexable,
        'noindex_reason', homepage.noindex_reason
      )
    )
  FROM public.homepage_pages homepage
  WHERE homepage.status <> 'archived';
  GET DIAGNOSTICS v_homepage_count = ROW_COUNT;

  INSERT INTO public.city_page_read_models (
    publication_version_id,
    city_id,
    locale,
    canonical_slug,
    payload
  )
  SELECT
    p_publication_version_id,
    city_page.city_id,
    city_page.locale,
    city_page.canonical_slug,
    jsonb_set(
      private.build_city_page_payload(jsonb_build_object(
      'city_slug', city_page.canonical_slug,
      'locale', city_page.locale,
      'route_direction', city_page.route_direction,
      'destination_limit', 20
      ))->'data',
      '{content_sections}',
      COALESCE((
        SELECT jsonb_agg(to_jsonb(section) - 'city_page_id' ORDER BY section.display_order)
        FROM public.city_content_sections section
        WHERE section.city_page_id = city_page.id
          AND section.locale = city_page.locale
          AND section.status = 'published'
      ), '[]'::JSONB),
      TRUE
    )
  FROM public.city_pages city_page
  WHERE city_page.route_direction = 'outbound'
    AND city_page.status <> 'archived';
  GET DIAGNOSTICS v_city_count = ROW_COUNT;

  INSERT INTO public.airport_page_read_models (
    publication_version_id,
    airport_id,
    locale,
    airport_iata,
    payload
  )
  SELECT
    p_publication_version_id,
    airport_page.airport_id,
    airport_page.locale,
    airport.iata,
    jsonb_set(
      private.build_airport_page_payload(jsonb_build_object(
      'airport_iata', airport.iata,
      'locale', airport_page.locale
      ))->'data',
      '{content_sections}',
      COALESCE((
        SELECT jsonb_agg(to_jsonb(section) - 'airport_page_id' ORDER BY section.display_order)
        FROM public.airport_content_sections section
        WHERE section.airport_page_id = airport_page.id
          AND section.locale = airport_page.locale
          AND section.status = 'published'
      ), '[]'::JSONB),
      TRUE
    )
  FROM public.airport_pages airport_page
  JOIN public.airports airport
    ON airport.id = airport_page.airport_id
  WHERE airport_page.status <> 'archived';
  GET DIAGNOSTICS v_airport_count = ROW_COUNT;

  INSERT INTO public.route_page_read_models (
    publication_version_id,
    route_page_id,
    locale,
    canonical_slug,
    payload
  )
  SELECT
    p_publication_version_id,
    route_page.id,
    route_page.locale,
    route_page.canonical_slug,
    private.build_route_page_payload(jsonb_build_object(
      'route_slug', route_page.canonical_slug,
      'locale', route_page.locale
    ))->'data'
  FROM public.route_pages route_page
  WHERE route_page.status <> 'archived';
  GET DIAGNOSTICS v_route_count = ROW_COUNT;

  RETURN jsonb_build_object(
    'homepage', v_homepage_count,
    'city', v_city_count,
    'airport', v_airport_count,
    'route', v_route_count
  );
END;
$$;

REVOKE ALL ON FUNCTION private.refresh_page_read_models(UUID)
FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION private.refresh_page_read_models(UUID) TO service_role;

-- >>> supabase/sql_src/functions/pseo/shared/publish_read_model_version.sql

-- ============================================================================
-- Function: public.publish_read_model_version
-- Purpose: Atomically build and publish one complete shared read-model version.
-- Responsibilities: Refresh route search and all page models before flipping the current marker.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.publish_read_model_version(p_source_type TEXT DEFAULT 'development_fixture')
RETURNS JSONB
LANGUAGE plpgsql
VOLATILE
SET search_path = ''
AS $$
DECLARE
  v_version_id UUID;
  v_route_count INTEGER;
  v_page_counts JSONB;
BEGIN
  IF p_source_type NOT IN ('production', 'development_fixture') THEN
    RETURN private.build_rpc_error(NULL, 'ERR_INVALID_REQUEST', 'Invalid publication source type.');
  END IF;

  -- STEP 01: Serialize publishers so two candidates cannot race the current marker.
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('tripways:read-model-publication', 0)
  );

  INSERT INTO public.publication_versions (source_type)
  VALUES (p_source_type)
  RETURNING id
  INTO v_version_id;

  -- STEP 02: Keep candidate failures in a subtransaction and preserve the current version.
  BEGIN
    v_route_count := private.refresh_route_search_options(v_version_id);
    v_page_counts := private.refresh_page_read_models(v_version_id);

    IF v_route_count = 0
      OR COALESCE((v_page_counts->>'homepage')::INTEGER, 0) = 0
    THEN
      RAISE EXCEPTION USING
        ERRCODE = '23514',
        MESSAGE = 'ERR_PUBLICATION_INCOMPLETE';
    END IF;
  EXCEPTION
    WHEN OTHERS THEN
      UPDATE public.publication_versions
      SET
        status = 'failed',
        failure_code = CASE
          WHEN SQLERRM ~ '^ERR_[A-Z0-9_]+$' THEN SQLERRM
          ELSE 'ERR_PUBLICATION_FAILED'
        END
      WHERE id = v_version_id;

      RETURN private.build_rpc_error(
        NULL,
        'ERR_PUBLICATION_FAILED',
        'Read-model publication failed.'
      );
  END;

  -- STEP 03: Flip all page and search readers to the complete candidate atomically.
  UPDATE public.publication_versions
  SET
    is_current = FALSE,
    status = 'retired'
  WHERE is_current = TRUE;

  UPDATE public.publication_versions
  SET
    status = 'published',
    is_current = TRUE,
    published_at = now()
  WHERE id = v_version_id;

  RETURN jsonb_build_object(
    'data', jsonb_build_object(
      'data_version', v_version_id,
      'route_options', v_route_count,
      'pages', v_page_counts
    ),
    'meta', jsonb_build_object('data_version', v_version_id, 'published_at', now()),
    'error', NULL
  );
END;
$$;

REVOKE ALL ON FUNCTION public.publish_read_model_version(TEXT)
FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.publish_read_model_version(TEXT) TO service_role;

-- >>> supabase/sql_src/functions/pseo/shared/rpc_get_page.sql

-- ============================================================================
-- Function: public.rpc_get_page
-- Purpose: Load one complete page from its dedicated current read model.
-- Responsibilities: Normalize identity and perform exactly one page-model lookup.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.rpc_get_page(p_input JSONB)
RETURNS JSONB
LANGUAGE plpgsql
STABLE
SET search_path = ''
AS $$
DECLARE
  v_page_type TEXT := p_input->>'page_type';
  v_entity_key TEXT := p_input->>'entity_key';
  v_locale TEXT := COALESCE(NULLIF(p_input->>'locale', ''), 'en-GB');
  v_version_id UUID;
  v_payload JSONB;
  v_generated_at TIMESTAMPTZ;
BEGIN
  IF jsonb_typeof(p_input) IS DISTINCT FROM 'object'
    OR p_input - ARRAY['page_type', 'entity_key', 'locale'] <> '{}'::JSONB
    OR v_page_type NOT IN ('homepage', 'city', 'airport', 'route')
    OR v_entity_key IS NULL
    OR v_locale !~ '^[a-z]{2}(?:-[A-Z]{2})?$'
  THEN
    RETURN private.build_rpc_error(NULL, 'ERR_INVALID_REQUEST', 'Invalid page request.');
  END IF;

  -- STEP 01: Select the requested row and its current version in one indexed statement.
  IF v_page_type = 'homepage' THEN
    SELECT model.payload, model.generated_at, version.id
    INTO v_payload, v_generated_at, v_version_id
    FROM public.homepage_read_models model
    INNER JOIN public.publication_versions version
      ON version.id = model.publication_version_id
      AND version.is_current = TRUE
    WHERE model.locale = v_locale;
  ELSIF v_page_type = 'city' THEN
    SELECT model.payload, model.generated_at, version.id
    INTO v_payload, v_generated_at, v_version_id
    FROM public.city_page_read_models model
    INNER JOIN public.publication_versions version
      ON version.id = model.publication_version_id
      AND version.is_current = TRUE
    WHERE model.canonical_slug = lower(v_entity_key)
      AND model.locale = v_locale;
  ELSIF v_page_type = 'airport' THEN
    SELECT model.payload, model.generated_at, version.id
    INTO v_payload, v_generated_at, v_version_id
    FROM public.airport_page_read_models model
    INNER JOIN public.publication_versions version
      ON version.id = model.publication_version_id
      AND version.is_current = TRUE
    WHERE model.airport_iata = upper(v_entity_key)
      AND model.locale = v_locale;
  ELSE
    SELECT model.payload, model.generated_at, version.id
    INTO v_payload, v_generated_at, v_version_id
    FROM public.route_page_read_models model
    INNER JOIN public.publication_versions version
      ON version.id = model.publication_version_id
      AND version.is_current = TRUE
    WHERE model.canonical_slug = lower(v_entity_key)
      AND model.locale = v_locale;
  END IF;

  IF v_payload IS NULL THEN
    RETURN private.build_rpc_error(NULL, 'ERR_PAGE_NOT_FOUND', 'Current page not found.');
  END IF;

  -- STEP 02: Return the materialized payload without rebuilding page modules at request time.
  RETURN jsonb_build_object(
    'data', v_payload,
    'meta', jsonb_build_object(
      'page_type', v_page_type,
      'entity_key', v_entity_key,
      'data_version', v_version_id,
      'generated_at', v_generated_at
    ),
    'error', NULL
  );
END;
$$;

REVOKE ALL ON FUNCTION public.rpc_get_page(JSONB)
FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.rpc_get_page(JSONB) TO service_role;
